const items = $input.all();
const RE_DOMAINE = /^(?=.{1,253}$)([a-z0-9-]{1,63}\.)+[a-z]{2,24}$/i;
const RE_IPV4 = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;
const RE_SHA256 = /^[a-f0-9]{64}$/i;
return items.map((it) => {
  const brut = String(it.json.valeur ?? '').trim().slice(0, 300);
  let type = 'invalide';
  if (RE_IPV4.test(brut)) type = 'ipv4';
  else if (RE_SHA256.test(brut)) type = 'sha256';
  else if (RE_DOMAINE.test(brut)) type = 'domaine';
  const defanged = brut.replace(/\./g, '[.]');
  return { json: { valeur: brut, type, defanged, accepte: type !== 'invalide', note: 'Aucun appel externe : enrichissement simulé' } };
});
